var NAME_ALIASES = { john: 'giannis', giannis: 'giannis', johannis: 'giannis' };
function meKey() {
  var n = String(localStorage.getItem('elysian_user_name') || '').trim().toLowerCase();
  if (!n || n === 'team member') return '';
  if (NAME_ALIASES[n]) {
    var ak = NAME_ALIASES[n];
    if ((cfg.team || []).some(function (t) { return t.key === ak; })) return ak;
  }
  var m = (cfg.team || []).filter(function (t) {
    return t.key === n || String(t.name || '').toLowerCase() === n;
  })[0];
  return m ? m.key : '';
}
// An assigned lead that is still open is an open task for that person.
// on_hold is parked, won/lost/erased/archived are done — none of those are tasks.
function isOpenTask(l) {
  return !!(l && l.owner && !l.archived_at && l.status === 'open' && l.stage !== 'on_hold');
}
