function taskRows(ownerFilter) {
  return rows.filter(function (l) {
    if (!isOpenTask(l)) return false;
    if (ownerFilter && l.owner !== ownerFilter) return false;
    return true;
  }).sort(function (a, b) {
    var sa = slaState(a) === 'late' ? 0 : slaState(a) === 'soon' ? 1 : 2;
    var sb = slaState(b) === 'late' ? 0 : slaState(b) === 'soon' ? 1 : 2;
    if (sa !== sb) return sa - sb;
    return new Date(a.created_time || a.updated_at || 0) - new Date(b.created_time || b.updated_at || 0);
  });
}

