function myTasksHtml(){
    var me=currentUser();
    if(!me) return '<div class="home-empty">Choose who you are (on Home) to see tasks assigned to you.</div>';
    var mine=tasksBag().filter(function(t){return t.assignee===me && !t.done;});
    var today=todayMid();
