    var byB={overdue:[],today:[],soon:[],week:[],later:[],nodate:[]};
    mine.forEach(function(t){ var d=parseDate(t.due); byB[bucketOf(d,today)].push({t:t,d:d,kind:'task'}); });
    order.forEach(function(k){ byB[k].sort(function(a,b){ return (a.d&&b.d)?(a.d-b.d):0; }); });
    var h='';
    // Assigned open leads are open tasks for this person — render into the same list.
    h+='<div id="home-lead-tasks-slot" class="home-bucket" style="display:none"></div>';
    order.forEach(function(k){ var rows=byB[k]; if(!rows.length)return; h+='<div class="home-bucket"><h3><span class="dot" style="background:'+dot[k]+'"></span>'+titles[k]+' <span class="cnt">'+rows.length+'</span></h3>'; rows.forEach(function(o){ var t=o.t; h+='<div class="home-row"><span class="dot" style="background:'+dot[k]+'"></span><div class="rl"><b>'+esc(t.text)+'</b><div class="meta">from '+esc(t.creator||'—')+(o.d?' · due '+fmtShort(o.d):'')+'</div></div><button class="btn sm ok" onclick="closeTask(\''+t.id+'\')"><i class="ti ti-check"></i> Done</button></div>'; }); h+='</div>'; });
    if(!mine.length) h+='<div class="home-empty" id="home-tasks-empty">No team tasks assigned to you.</div>';
    setTimeout(function(){ try{ if(typeof window.refreshHomeLeads==='function') window.refreshHomeLeads(); }catch(e){} }, 0);
    return h;
  }

window.refreshHomeLeads=function(){
  var slot=document.getElementById('home-lead-tasks-slot');
  var empty=document.getElementById('home-tasks-empty');
  var countEl=document.getElementById('home-lead-count');
  var NEXT={new:'Make first contact',to_contact:'Make first contact',contacted:'Qualify the property',qualified:'Book a viewing',viewing:'Send a proposal',proposal:'Send the contract',contract_sent:'Chase the signature',signed:'Start onboarding',onboarding:'Mark live'};
  var LABEL={new:'New',to_contact:'To contact',contacted:'Contacted',qualified:'Qualified',viewing:'Viewing',proposal:'Proposal',contract_sent:'Contract sent',signed:'Signed',onboarding:'Onboarding'};
  function paint(pack){
    var mine=pack.mine||[];
    if(countEl) countEl.textContent=String(mine.length);
    if(!slot) return;
    if(!pack.me || !mine.length){ slot.style.display='none'; return; }
    if(empty && empty.parentNode) empty.parentNode.removeChild(empty);
    slot.style.display='';
    slot.innerHTML='<h3><span class="dot" style="background:var(--gold)"></span>Open leads <span class="cnt">'+mine.length+'</span></h3>'+
      mine.slice(0,10).map(function(l){
        var act=NEXT[l.stage]||'Open the ticket';
        var sub=(LABEL[l.stage]||l.stage)+(l.property_address?(' · '+l.property_address):'');
        return '<div class="home-row" style="cursor:pointer" onclick="ldGoTask('+l.id+')"><span class="dot" style="background:var(--gold)"></span><div class="rl"><b>'+esc(l.full_name||'(no name)')+'</b><div class="meta">Lead · '+esc(sub)+'</div></div><span class="lnk">'+esc(act)+' →</span></div>';
      }).join('')+(mine.length>10?'<div class="home-empty">+'+(mine.length-10)+' more on Leads</div>':'');
  }
  if(typeof window.ldFetchMyTasks==='function'){
    window.ldFetchMyTasks().then(paint).catch(function(){ if(countEl) countEl.textContent='—'; });
  } else if(countEl){ countEl.textContent='—'; }
};
